// #59e715 (193a63d7d3f3e0502e59e715) — боковое меню Super Admin: пункт «בקשות מידע» (4-й, со значком) ведёт на
// /admin/data-requests и там активен; у «התנתקות» есть значок; меню одинаково во всех разделах. Кейс ADM-002.
// Только чтение → @prod-safe.
import * as path from 'path';
import { test, expect, Page } from '@playwright/test';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const HASH = '#59e715 · #193a63d7d3f3e0502e59e715';
const ITEMS = ['בתי עסק', 'רישום גישה', 'תמיכה ותפעול', 'בקשות מידע', 'ספקי AI ותמלול', 'תבניות סימולציה'];
const SECTIONS = ['/admin/businesses', '/admin/access-log', '/admin/support', '/admin/data-requests', '/admin/providers', '/admin/templates'];
const DATA_REQUESTS_H1 = 'בקשות עיון ומחיקת מידע';

const nav = (page: Page) => page.getByTestId('app-sidebar').getByRole('navigation', { name: 'ניווט ראשי' });

/** Размер и источник значка внутри элемента меню. */
async function icon(el: ReturnType<Page['locator']>) {
  const img = el.locator('img').first();
  await expect(img).toBeVisible();
  const box = await img.boundingBox();
  return { src: (await img.getAttribute('src')) || '', w: Math.round(box?.width ?? 0), h: Math.round(box?.height ?? 0) };
}

test.describe(`Админка — боковое меню Super Admin (${HASH})`, () => {
  test(`меню на 6 разделах: порядок пунктов, «בקשות מידע» 4-й со своим значком, «התנתקות» со значком @desktop @prod-safe ${HASH}`, async ({ page }) => {
    for (const url of SECTIONS) {
      await page.goto(url);
      const links = nav(page).getByRole('link');
      // Источник: AC1 + Figma 812:448 / 816:1183 — 6 пунктов, «בקשות מידע» между «תמיכה ותפעול» и «ספקי AI ותמלול».
      await expect(links, `меню на ${url}`).toHaveText(ITEMS);
      await expect(links.nth(3)).toHaveAttribute('href', '/admin/data-requests');

      const icons = [];
      for (let i = 0; i < ITEMS.length; i++) {
        const ic = await icon(links.nth(i));
        expect([ic.w, ic.h], `значок «${ITEMS[i]}» на ${url}`).toEqual([20, 20]);
        icons.push(ic.src);
      }
      // Значок «בקשות מידע» свой (щит), не повтор чужого.
      expect(icons.filter((s) => s === icons[3]), `значок «בקשות מידע» совпадает с другим пунктом на ${url}`).toHaveLength(1);

      // Источник: AC2 — строка выхода со значком из кадра (icon/logout).
      const logout = page.getByTestId('logout-button');
      await expect(logout).toHaveText('התנתקות');
      const lo = await icon(logout);
      expect([lo.w, lo.h], `значок «התנתקות» на ${url}`).toEqual([20, 20]);
      expect(lo.src, 'значок выхода — icon/logout').toContain('icon/logout');
    }
  });

  test(`«בקשות מידע» → /admin/data-requests, h1 «${DATA_REQUESTS_H1}», пункт активен; после перезагрузки так же @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await page.goto('/admin/businesses');
    await nav(page).getByRole('link', { name: 'בקשות מידע' }).click();
    await page.waitForURL(/\/admin\/data-requests$/);

    for (const step of ['клик', 'перезагрузка']) {
      if (step === 'перезагрузка') await page.reload();
      // Источник: AC1 «והוא פותח את בקשות המידע»; S-22 «כניסה — מתפריט ה-Super Admin».
      await expect(page.getByRole('heading', { level: 1, name: DATA_REQUESTS_H1 })).toBeVisible();
      // Источник: Figma 822:2114 — активен пункт «בקשות מידע».
      await expect(nav(page).getByRole('link', { name: 'בקשות מידע' })).toHaveAttribute('aria-current', 'page');
      await expect(nav(page).locator('a[aria-current="page"]'), `активных пунктов после «${step}»`).toHaveCount(1);
    }
  });
});
